import base64
import io
import customtkinter as ctk
from PIL import Image
from ui.theme import COLORS, FONTS, PAD, RADIUS, SIDEBAR_WIDTH

_LOGO_B64 = (
    ""
)

_cache = {}

def get_logo_image(size=52):
    if size in _cache:
        return _cache[size]
    try:
        raw = base64.b64decode(_LOGO_B64)
        img = Image.open(io.BytesIO(raw)).convert("RGBA")
        ctk_img = ctk.CTkImage(light_image=img, dark_image=img, size=(size, size))
        _cache[size] = ctk_img
        return ctk_img
    except Exception:
        _cache[size] = None
        return None

class Sidebar(ctk.CTkFrame):
    """
    Persistent left navigation. Highlights the active page and calls
    back into the App controller to switch frames.
    """

    NAV_ITEMS = [
        ("dashboard",  "\u2302  Dashboard",                    COLORS["accent_blue"]),
        ("cameras",    "\U0001F4F9  Cameras",                   COLORS["live"]),
        ("alerts",     "\u26A0  Alerts",                        COLORS["danger"]),
        ("events",     "\u25c9  Events",                        COLORS["evidence"]),
        ("personnel",  "\U0001F464  Personnel",                 COLORS["whitelist"]),
        ("analytics",  "\u25b2  Analytics",                     COLORS["training"]),
        ("settings",   "\u2699  Settings",                      COLORS["config"]),
        ("system",     "\u25cf  System",                        COLORS["live"]),
    ]

    def __init__(self, master, on_navigate):
        super().__init__(master, width=SIDEBAR_WIDTH, fg_color="#0E1A2B",
                  corner_radius=0, border_width=1, border_color="#233752")
        self.grid_propagate(False)
        self.on_navigate = on_navigate
        self.buttons = {}

        brand = ctk.CTkFrame(self, fg_color="transparent")
        brand.pack(fill="x", padx=PAD["md"], pady=(PAD["lg"], PAD["md"]))

        logo_img = get_logo_image(size=52)
        if logo_img is not None:
            ctk.CTkLabel(brand, image=logo_img, text="").pack(anchor="w")

        ctk.CTkLabel(brand, text="NETRA", font=(FONTS["h1"][0], 22, "bold"),
                     text_color=COLORS["sidebar_text"]).pack(anchor="w", pady=(PAD["sm"], 0))
        ctk.CTkLabel(brand, text="SEE.  DETECT.  PROTECT.", font=("Segoe UI", 9),
                     text_color=COLORS["accent_blue"]).pack(anchor="w")
        ctk.CTkLabel(brand, text="Border Surveillance — SIH26187", font=FONTS["small"],
                     text_color=COLORS["sidebar_muted"]).pack(anchor="w", pady=(2, 0))

        ctk.CTkFrame(self, height=1, fg_color="#233752").pack(
            fill="x", padx=PAD["md"], pady=(0, PAD["md"]))

        for key, label, accent in self.NAV_ITEMS:
            btn = ctk.CTkButton(
                self, text=label, anchor="w", height=42,
                corner_radius=RADIUS["sm"],
                fg_color="transparent", hover_color=COLORS["sidebar_alt"],
                text_color=COLORS["sidebar_muted"], font=FONTS["body"],
                command=lambda k=key: self._select(k),
            )
            btn.pack(fill="x", padx=PAD["sm"], pady=2)
            self.buttons[key] = (btn, accent)

        footer = ctk.CTkFrame(self, fg_color="transparent")
        footer.pack(side="bottom", fill="x", padx=PAD["md"], pady=PAD["md"])
        ctk.CTkFrame(self, height=1, fg_color="#233752").pack(
            side="bottom", fill="x", padx=PAD["md"], pady=(0, PAD["sm"]))
        self.status_dot = ctk.CTkLabel(footer, text="\u25CF", text_color=COLORS["success"],
                                        font=FONTS["small"])
        self.status_dot.pack(side="left")
        ctk.CTkLabel(footer, text="System Ready", font=FONTS["small"],
                     text_color=COLORS["sidebar_muted"]).pack(side="left", padx=(6, 0))

    def _select(self, key):
        self.on_navigate(key)

    def set_active(self, key):
        for k, (btn, accent) in self.buttons.items():
            if k == key:
                btn.configure(fg_color=COLORS["sidebar_alt"], text_color=accent,
                              font=FONTS["body_bold"])
            else:
                btn.configure(fg_color="transparent", text_color=COLORS["sidebar_muted"],
                              font=FONTS["body"])


class PageHeader(ctk.CTkFrame):
    def __init__(self, master, title, subtitle=None, accent=None, right_widget=None):
        super().__init__(master, fg_color="transparent")
        accent = accent or COLORS["accent_blue"]

        left = ctk.CTkFrame(self, fg_color="transparent")
        left.pack(side="left", fill="x", expand=True)

        bar = ctk.CTkFrame(left, width=4, height=28, fg_color=accent, corner_radius=2)
        bar.pack(side="left", padx=(0, PAD["sm"]))

        text_col = ctk.CTkFrame(left, fg_color="transparent")
        text_col.pack(side="left")
        ctk.CTkLabel(text_col, text=title, font=FONTS["h1"],
                     text_color=COLORS["text_primary"]).pack(anchor="w")
        if subtitle:
            ctk.CTkLabel(text_col, text=subtitle, font=FONTS["small"],
                         text_color=COLORS["text_secondary"]).pack(anchor="w")

        if right_widget is not None:
            right_widget(self).pack(side="right")


class Card(ctk.CTkFrame):
    def __init__(self, master, **kwargs):
        super().__init__(master, fg_color=COLORS["bg_panel"],
                          corner_radius=RADIUS["md"],
                          border_width=1, border_color=COLORS["border"], **kwargs)


class StatTile(Card):
    def __init__(self, master, label, value, accent, suffix=""):
        super().__init__(master)
        inner = ctk.CTkFrame(self, fg_color="transparent")
        inner.pack(fill="both", expand=True, padx=PAD["md"], pady=PAD["md"])

        ctk.CTkLabel(inner, text=label.upper(), font=FONTS["small_bold"],
                     text_color=COLORS["text_muted"]).pack(anchor="w")

        val_row = ctk.CTkFrame(inner, fg_color="transparent")
        val_row.pack(anchor="w", pady=(PAD["xs"], 0))
        self.val_label = ctk.CTkLabel(val_row, text=str(value), font=FONTS["display"],
                                      text_color=accent)
        self.val_label.pack(side="left")
        if suffix:
            ctk.CTkLabel(val_row, text=suffix, font=FONTS["body"],
                         text_color=COLORS["text_secondary"]).pack(side="left", padx=(4, 0), pady=(8, 0))

    def update_value(self, value):
        self.val_label.configure(text=str(value))


class Pill(ctk.CTkLabel):
    def __init__(self, master, text, color):
        super().__init__(master, text=f"  {text}  ", font=FONTS["small_bold"],
                          text_color="#0B1220", fg_color=color, corner_radius=RADIUS["sm"])


def PrimaryButton(master, text, command=None, accent=None, **kwargs):
    accent = accent or COLORS["accent_blue"]
    hover = COLORS["accent_blue_hover"] if accent == COLORS["accent_blue"] else accent
    return ctk.CTkButton(
        master, text=text, command=command, height=38, corner_radius=RADIUS["sm"],
        fg_color=accent, hover_color=hover, text_color="#FFFFFF",
        font=FONTS["body_bold"], **kwargs,
    )


def SecondaryButton(master, text, command=None, **kwargs):
    return ctk.CTkButton(
        master, text=text, command=command, height=38, corner_radius=RADIUS["sm"],
        fg_color="transparent", hover_color=COLORS["bg_panel_alt"],
        text_color=COLORS["text_primary"], border_width=1, border_color=COLORS["border"],
        font=FONTS["body"], **kwargs,
    )

def ThirdButton(master, text, command=None, **kwargs):
    return ctk.CTkButton(
        master, text=text, command=command, height=38, corner_radius=RADIUS["sm"],
        fg_color="transparent", hover_color=COLORS["bg_panel_alt"],
        text_color=COLORS["text_secondary"], border_width=1, border_color=COLORS["border"],
        font=FONTS["body"], **kwargs,
    )

class ScrollPage(ctk.CTkScrollableFrame):
    def __init__(self, master, **kwargs):
        super().__init__(master, fg_color=COLORS["bg_base"],
                          scrollbar_button_color=COLORS["border"],
                          scrollbar_button_hover_color=COLORS["accent_blue"], **kwargs)
